    // MARK: - Text-Based Detection Tests

    @Suite("Text Detection")
    struct TextDetectionTests {

        @Test("Detects fillers in raw text")
        func detectsInText() async {
            // Arrange
            let detector = SmartFillerDetector()
            let text = "So um I was thinking uh about this"

            // Act
            let fillers = await detector.detectFillers(in: text)

            // Assert
            #expect(fillers.count >= 2)  // At least "um" and "uh"
            let fillerWords = fillers.map { $0.word }
            #expect(fillerWords.contains("um"))
            #expect(fillerWords.contains("uh"))
        }

        @Test("Returns ranges for filler positions")
        func returnsRanges() async {
            // Arrange
            let detector = SmartFillerDetector()
            let text = "Hello um world"

            // Act
            let fillers = await detector.detectFillers(in: text)

            // Assert
            for filler in fillers {
                let extractedWord = String(text[filler.range])
                #expect(extractedWord.lowercased() == filler.word)
            }
        }

        @Test("Empty text returns empty")
        func emptyTextReturnsEmpty() async {
            // Arrange
            let detector = SmartFillerDetector()
            let text = ""

            // Act
            let fillers = await detector.detectFillers(in: text)

            // Assert
            #expect(fillers.isEmpty)
        }
    }

