            // Assert
            #expect(confidence >= 0.9)
        }

        @Test("Non-filler has zero confidence")
        func nonFillerZeroConfidence() async {
            // Arrange
            let detector = SmartFillerDetector()

            // Act
            let confidence = await detector.fillerConfidence(for: "hello", in: "hello world")

            // Assert
            #expect(confidence == 0.0)
        }

        @Test("Confidence is between 0 and 1")
        func confidenceInRange() async {
            // Arrange
            let detector = SmartFillerDetector()
            let testWords = ["um", "like", "hello", "actually", "basically"]

            // Act & Assert
            for word in testWords {
                let confidence = await detector.fillerConfidence(for: word, in: "Testing \(word) in context")
                #expect(confidence >= 0.0)
                #expect(confidence <= 1.0)
            }
        }

        @Test("Contextual filler has medium confidence")
        func contextualFillerMediumConfidence() async {
            // Arrange
            let detector = SmartFillerDetector()

            // Act
            let confidence = await detector.fillerConfidence(for: "like", in: "It was like totally cool")

            // Assert - contextual fillers should have lower confidence than definite ones
            #expect(confidence > 0.0)
            #expect(confidence < 0.95)
        }
    }

