        @Test("Handles punctuation around fillers")
        func handlesPunctuation() async {
            // Arrange
            let detector = SmartFillerDetector()
            let words = [
                CaptionWord(text: "um,", start: 0, end: 0.3, probability: 0.9),
                CaptionWord(text: "uh.", start: 0.3, end: 0.5, probability: 0.9)
            ]

            // Act
            let fillers = await detector.detectFillers(in: words)

            // Assert - should still detect despite punctuation
            #expect(fillers.contains(0))
            #expect(fillers.contains(1))
        }

        @Test("Handles single word input")
        func handlesSingleWord() async {
            // Arrange
            let detector = SmartFillerDetector()
            let words = [CaptionWord(text: "um", start: 0, end: 0.5, probability: 0.9)]

            // Act
            let fillers = await detector.detectFillers(in: words)

            // Assert
            #expect(fillers.count == 1)
        }

        @Test("Handles long sentence")
        func handlesLongSentence() async {
            // Arrange
            let detector = SmartFillerDetector()
            var words: [CaptionWord] = []
            let sentence = "The quick brown fox um jumps uh over the lazy dog and um that is all"
            var time = 0.0

            for word in sentence.split(separator: " ") {
                words.append(CaptionWord(text: String(word), start: time, end: time + 0.3, probability: 0.9))
                time += 0.3
            }

            // Act
            let fillers = await detector.detectFillers(in: words)

            // Assert - should find "um" and "uh"
            #expect(fillers.count >= 2)
        }

        @Test("Handles mixed case and punctuation in text")
        func handlesMixedCasePunctuation() async {
            // Arrange
            let detector = SmartFillerDetector()
            let text = "So, UM... I was, uh, thinking."

            // Act
            let fillers = await detector.detectFillers(in: text)

            // Assert
            let fillerWords = fillers.map { $0.word.lowercased() }
            #expect(fillerWords.contains("um"))
            #expect(fillerWords.contains("uh"))
        }

        @Test("Handles hyphenated fillers")
        func handlesHyphenatedFillers() async {
            // Arrange
            let detector = SmartFillerDetector()
            let words = [
                CaptionWord(text: "uh-huh", start: 0, end: 0.5, probability: 0.9),
                CaptionWord(text: "mm-hmm", start: 0.5, end: 1.0, probability: 0.9)
            ]

            // Act
            let fillers = await detector.detectFillers(in: words)

            // Assert
            #expect(fillers.count == 2)
        }
    }

